(x, y, t) => {
  const s = [
    [120+Math.sin(t*0.7)*80, 60+Math.cos(t*0.5)*40],
    [360+Math.cos(t*0.6)*80, 50+Math.sin(t*0.8)*35],
    [80+Math.sin(t*0.4+2)*90, 180+Math.cos(t*0.6+1)*50],
    [400+Math.cos(t*0.5+3)*70, 170+Math.sin(t*0.7+2)*45],
    [240+Math.sin(t*0.3)*120, 120+Math.cos(t*0.4+1)*80],
    [240+Math.cos(t*0.35+1.5)*100, 120+Math.sin(t*0.45+0.5)*70]
  ];
  const d = s.map(p => Math.sqrt((x-p[0])**2+(y-p[1])**2));
  const w = d.map((di,i) => {
    const f=0.06+i*0.012, sp=1.8+i*0.3, ph=i*1.2;
    return Math.sin(di*f-t*sp+ph)+Math.sin(di*f*2.1-t*sp*0.7)*0.3;
  });
  const activator=(w[0]+w[1]+w[2]+w[3])*0.25;
  const inhibitor=(w[2]+w[3]+w[4]+w[5])*0.25;
  const feed=0.04+Math.sin(t*0.2)*0.01, kill=0.06+Math.cos(t*0.15)*0.01;
  const reaction=Math.tanh((activator-inhibitor*1.2+feed-kill)*3);
  const warpX=Math.sin(y*0.02+t*0.5)*15+Math.cos(y*0.035-t*0.3)*10;
  const warpY=Math.sin(x*0.025-t*0.4)*15+Math.cos(x*0.03+t*0.6)*10;
  const wx=x+warpX, wy=y+warpY;
  const wd=s.map(p=>Math.sqrt((wx-p[0])**2+(wy-p[1])**2));
  const ww=wd.map((di,i)=>Math.sin(di*0.08-t*1.5+i*0.8));
  const warpedField=(ww[0]+ww[2]+ww[4]-ww[1]-ww[3]-ww[5])/6;
  const moire1=Math.sin(x*0.15+y*0.08+t*0.6)*Math.sin(x*0.08-y*0.15+t*0.9);
  const moire2=Math.sin((x+y)*0.12-t*1.2)*Math.sin((x-y)*0.1+t*0.8);
  const moire=(moire1+moire2)*0.15*(0.5+0.5*reaction);
  const cx=240,cy=120,dist=Math.sqrt((x-cx)**2+(y-cy)**2);
  const ang=Math.atan2(y-cy,x-cx);
  const spiral=Math.sin(dist*0.05-ang*3-t*1.2)*Math.exp(-dist*0.003);
  const combined=reaction*0.5+warpedField*0.25+moire+spiral*0.15;
  const v=Math.tanh(combined*2)*0.5+0.5;
  const pal=[[8,12,48],[15,50,95],[25,120,140],[60,185,170],[220,195,80],[240,140,50],[180,50,40],[60,20,60],[8,12,48]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(combined*Math.PI*2)*0.1+Math.exp(-dist*0.004)*0.1;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum)|0
  ];
}
